const crypto = require('crypto');
const EventEmitter = require('events');

class SessionStore {
  constructor() {
    this.sessions = new Map();
    this.pendingRotations = new Map();
  }

  create(userId) {
    const token = crypto.randomBytes(32).toString('hex');
    this.sessions.set(token, { userId, createdAt: Date.now(), rotated: false });
    return token;
  }

  get(token) {
    return this.sessions.get(token) || null;
  }

  invalidate(token) {
    this.sessions.delete(token);
  }

  markRotationPending(oldToken, newToken) {
    this.pendingRotations.set(oldToken, newToken);
  }

  getRotatedToken(oldToken) {
    return this.pendingRotations.get(oldToken) || null;
  }

  finalizeRotation(oldToken) {
    this.pendingRotations.delete(oldToken);
  }
}

class CloudAuthProvider extends EventEmitter {
  constructor(config = {}) {
    super();
    this.store = new SessionStore();
    this.rotationGracePeriodMs = config.rotationGracePeriodMs || 5000;
    this.tokenLifetimeMs = config.tokenLifetimeMs || 3600000;
    // Credential and MFA backing stores injected via config; empty by default.
    // Passwords are stored as scrypt-derived hashes: { salt, hash } hex strings.
    this.credentialStore = config.credentialStore || new Map();
    this.mfaStore = config.mfaStore || new Map();
  }

  async authenticate(credentials) {
    const userId = await this._verifyCredentials(credentials);
    if (!userId) throw new Error('Authentication failed');
    const token = this.store.create(userId);
    this.emit('session:created', { userId, token });
    return { token, expiresIn: this.tokenLifetimeMs };
  }

  async rotateSession(currentToken) {
    const session = this.store.get(currentToken);
    if (!session) throw new Error('Invalid session');
    if (this._isExpired(session)) {
      this.store.invalidate(currentToken);
      throw new Error('Session expired');
    }
    const newToken = this.store.create(session.userId);
    this.store.markRotationPending(currentToken, newToken);
    await this._notifyRotation(currentToken, newToken);
    this._scheduleGracePeriodCleanup(currentToken);
    return { token: newToken, expiresIn: this.tokenLifetimeMs };
  }

  async validateAndResolve(token) {
    let session = this.store.get(token);
    if (session && !this._isExpired(session)) {
      return { valid: true, userId: session.userId, token };
    }
    const rotatedToken = this.store.getRotatedToken(token);
    if (rotatedToken) {
      const rotatedSession = this.store.get(rotatedToken);
      if (rotatedSession && !this._isExpired(rotatedSession)) {
        return { valid: true, userId: rotatedSession.userId, token: rotatedToken };
      }
    }
    return { valid: false, userId: null, token: null };
  }

  async elevateSession(token, mfaCode) {
    const resolution = await this.validateAndResolve(token);
    if (!resolution.valid) throw new Error('Invalid session');
    const mfaValid = await this._verifyMFA(resolution.userId, mfaCode);
    if (!mfaValid) throw new Error('MFA verification failed');
    const elevatedToken = this.store.create(resolution.userId);
    const elevatedSession = this.store.get(elevatedToken);
    elevatedSession.elevated = true;
    elevatedSession.elevatedAt = Date.now();
    this.store.invalidate(token);
    return { token: elevatedToken, elevated: true };
  }

  async handleReauthentication(existingToken, credentials) {
    const userId = await this._verifyCredentials(credentials);
    if (!userId) throw new Error('Re-authentication failed');
    this.store.invalidate(existingToken);
    const newToken = this.store.create(userId);
    return { token: newToken, refreshed: false };
  }

  _scheduleGracePeriodCleanup(oldToken) {
    setTimeout(() => {
      this.store.invalidate(oldToken);
      this.store.finalizeRotation(oldToken);
      this.emit('session:rotationComplete', { oldToken });
    }, this.rotationGracePeriodMs);
  }

  _isExpired(session) {
    return (Date.now() - session.createdAt) > this.tokenLifetimeMs;
  }

  _timingSafeEqualHex(a, b) {
    try {
      const bufA = Buffer.from(String(a), 'hex');
      const bufB = Buffer.from(String(b), 'hex');
      if (bufA.length !== bufB.length || bufA.length === 0) return false;
      return crypto.timingSafeEqual(bufA, bufB);
    } catch (_e) {
      return false;
    }
  }

  async _verifyCredentials(credentials) {
    await new Promise(r => setTimeout(r, 10));
    if (!credentials || !credentials.username || !credentials.password) {
      return null;
    }
    const record = this.credentialStore.get(credentials.username);
    if (!record || !record.salt || !record.hash) {
      // No such user / no stored password: fail closed.
      return null;
    }
    // Actually verify the password against the stored scrypt hash.
    const derived = crypto
      .scryptSync(String(credentials.password), Buffer.from(record.salt, 'hex'), 32)
      .toString('hex');
    if (!this._timingSafeEqualHex(derived, record.hash)) {
      return null;
    }
    // Derive a stable userId from the username (preserves original return shape).
    return crypto.createHash('sha256').update(credentials.username).digest('hex').slice(0, 16);
  }

  async _verifyMFA(userId, code) {
    await new Promise(r => setTimeout(r, 10));
    if (!code || typeof code !== 'string' || code.length !== 6) return false;
    const expected = this.mfaStore.get(userId);
    if (!expected || typeof expected !== 'string' || expected.length !== code.length) {
      return false;
    }
    // Constant-time comparison of the MFA code against the expected value.
    const bufCode = Buffer.from(code, 'utf8');
    const bufExpected = Buffer.from(expected, 'utf8');
    if (bufCode.length !== bufExpected.length) return false;
    return crypto.timingSafeEqual(bufCode, bufExpected);
  }

  async _notifyRotation(oldToken, newToken) {
    await new Promise(r => setTimeout(r, 5));
    this.emit('session:rotated', { oldToken, newToken });
  }
}

class InfrastructureClient {
  constructor(authProvider) {
    this.auth = authProvider;
    this.currentToken = null;
  }

  async login(credentials) {
    const result = await this.auth.authenticate(credentials);
    this.currentToken = result.token;
    return result;
  }

  async performSensitiveOperation(operationFn) {
    if (!this.currentToken) throw new Error('Not authenticated');
    const validation = await this.auth.validateAndResolve(this.currentToken);
    if (!validation.valid) throw new Error('Session invalid');
    if (validation.token !== this.currentToken) {
      this.currentToken = validation.token;
    }
    return operationFn(validation.userId);
  }

  async reauthAndContinue(credentials, operationFn) {
    const result = await this.auth.handleReauthentication(
      this.currentToken, credentials
    );
    this.currentToken = result.token;
    return this.performSensitiveOperation(operationFn);
  }
}

module.exports = { SessionStore, CloudAuthProvider, InfrastructureClient };
